      "id": "C0564",
      "sceneId": 167,
      "sequence": "1/1",
      "chapter": "Day 7｜八瀨、瑠璃光院、大原與三千院",
      "imageSource": "A01-京都/T02-167.png",
      "start": 2006.989,
      "end": 2008.799,
      "startMs": 2006989,
      "endMs": 2008799,
      "duration": 1.8099999999999454,
      "text": "早上先前往出町柳。",
